<?php declare(strict_types=1);require_once dirname(__DIR__).'/_bootstrap.php';apiMethod('POST','PUT');apiCsrf();$uid=apiAuth();$in=apiInput();$id=apiId($in['id']??0);$s=apiDb()->prepare("UPDATE orders SET order_status='Cancelled' WHERE id=? AND user_id=? AND order_status IN ('Pending','Processing')");$s->execute([$id,$uid]);if(!$s->rowCount())apiError('Order cannot be cancelled',409);apiResponse(['id'=>$id,'order_status'=>'Cancelled']);